    mr,mc=min(r for r,c in pts),min(c for r,c in pts); sh=[(r-mr,c-mc) for r,c in pts]
    h=max(r for r,c in sh)+1; w=max(c for r,c in sh)+1; H,W=len(g),len(g[0])
